Write-Host 'Ajout du bouton copier le numero Wave / Orange Money...' -ForegroundColor Cyan
Write-FileFromBase64 -RelativePath "components/cart-page-client.tsx" -Base64Content $b64_0

Write-Host ""
Write-Host "Modification appliquee avec succes !" -ForegroundColor Green
Write-Host "Un bouton Copier le numero apparait maintenant a cote du numero Wave/Orange Money au checkout." -ForegroundColor Green
Write-Host ""
$confirm = Read-Host "Voulez-vous faire git add / commit / push maintenant ? (o/n)"
if ($confirm -eq 'o' -or $confirm -eq 'O') {
    git add components/cart-page-client.tsx
    git commit -m "Feat: ajoute un bouton pour copier le numero Wave/Orange Money en un clic"
    git push
    Write-Host "Pousse sur Git avec succes !" -ForegroundColor Green
} else {
    Write-Host "Pas de push. Vous pouvez le faire plus tard avec : git add . ; git commit -m '...' ; git push" -ForegroundColor Yellow
}
